import random

class Solution:
    def __init__(self, head):
        self.head = head

    def getRandom(self) -> int:
        result = 0
        node = self.head
        i = 1
        while node:
            if random.randint(1, i) == 1:
                result = node.val
            node = node.next
            i += 1
        return result

